mapper.select:
SELECT st.student_id as userId,st.name AS userName,st.clazz as postOrClazz, u.height,u.weight,u.fat_percentage,u.BMI,u.type,u.measure_time,u.sleep_time_total,u.deep_sleep_total,u.light_sleep_total, u.wake_time_total,u.list_sleep_time,u.today_wakeup_time,u.step,u.walking_distance,u.walking_time,u.calorie,u.mean_resting_heart_rate, u.resting_heart_rate_max,u.resting_heart_rate_min,u.spo2,u.temperature FROM user_health u LEFT JOIN student st ON u.user_id = st.student_id where u.user_id = st.student_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT st.teacher_id as userId,st.name AS userName,st.post as postOrClazz, u.height,u.weight,u.fat_percentage,u.BMI,u.type,u.measure_time,u.sleep_time_total,u.deep_sleep_total,u.light_sleep_total, u.wake_time_total,u.list_sleep_time,u.today_wakeup_time,u.step,u.walking_distance,u.walking_time,u.calorie,u.mean_resting_heart_rate, u.resting_heart_rate_max,u.resting_heart_rate_min,u.spo2,u.temperature FROM user_health u LEFT JOIN teacher st ON u.user_id = st.teacher_id where u.user_id = st.teacher_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT st.logistics_id as userId,st.name AS userName,st.post as postOrClazz, u.height,u.weight,u.fat_percentage,u.BMI,u.type,u.measure_time,u.sleep_time_total,u.deep_sleep_total,u.light_sleep_total, u.wake_time_total,u.list_sleep_time,u.today_wakeup_time,u.step,u.walking_distance,u.walking_time,u.calorie,u.mean_resting_heart_rate, u.resting_heart_rate_max,u.resting_heart_rate_min,u.spo2,u.temperature FROM user_health u LEFT JOIN logistics st ON u.user_id = st.logistics_id where u.user_id = st.logistics_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}
